fn from_be_hex(hex: &str) -> [u8; 32] {
    assert_eq!(hex.len(), 64);
    let mut bytes = [0u8; 32];
    for i in 0..32 {
        bytes[31 - i] =
            u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).expect("packet vector contains hex");
    }
    bytes
}

#[test]
fn matches_all_289_frozen_packet_vectors() {
    let rows: Vec<_> = VECTORS.trim().lines().collect();
    assert_eq!(rows.len(), 289);
    for row in rows {
        let mut fields = row.split('|');
        let mut left = from_be_hex(fields.next().expect("left"));
        let right = from_be_hex(fields.next().expect("right"));
        let expected_result = from_be_hex(fields.next().expect("result"));
        let expected_borrow = fields
            .next()
            .expect("borrow")
            .parse::<u8>()
            .expect("borrow byte");
        assert!(fields.next().is_none());

        let mut out = [0u8; 33];
        subtract(&mut left, &right, &mut out);

        assert_eq!(left, expected_result, "{row}");
        assert_eq!(&out[..32], &expected_result, "{row}");
        assert_eq!(out[32], expected_borrow, "{row}");
    }
}
